import React, { useEffect, useRef, useState } from "react";

/**
 * FinalSection:
 * Emotional grand finale.
 * Features warm illumination, grand typography, and an elegant champagne & rose
 * floating confetti, star dust, and subtle glowing heart particle canvas.
 */
export const FinalSection = ({ config, onReplay }) => {
  const [isRevealed, setIsRevealed] = useState(false);
  const sectionRef = useRef(null);
  const canvasRef = useRef(null);

  useEffect(() => {
    const el = sectionRef.current;
    if (!el) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsRevealed(true);
        }
      },
      { threshold: 0.3 }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Elegant luxury confetti & hearts celebration canvas
  useEffect(() => {
    if (!isRevealed) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let animId;
    let width = (canvas.width = canvas.parentElement.offsetWidth);
    let height = (canvas.height = canvas.parentElement.offsetHeight);

    const prefersReducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    if (prefersReducedMotion) return;

    // Palette: champagne, soft rose, blush, muted gold, off-white
    const palette = [
      "rgba(232, 216, 200, ", // champagne
      "rgba(226, 164, 153, ", // soft rose
      "rgba(246, 213, 205, ", // blush
      "rgba(245, 236, 226, ", // warm off-white
      "rgba(212, 175, 140, ", // gentle gold
    ];

    const particleCount = window.innerWidth < 768 ? 40 : 75;
    const items = [];

    // Particle types: 'confetti', 'star', 'heart'
    for (let i = 0; i < particleCount; i++) {
      items.push({
        x: Math.random() * width,
        y: Math.random() * height - height * 0.5,
        type: i % 7 === 0 ? "heart" : i % 4 === 0 ? "star" : "ribbon",
        size: Math.random() * 5 + 4,
        colorBase: palette[Math.floor(Math.random() * palette.length)],
        alpha: Math.random() * 0.6 + 0.3,
        vx: (Math.random() - 0.5) * 0.8,
        vy: Math.random() * 1.2 + 0.6,
        rotation: Math.random() * Math.PI * 2,
        rotSpeed: (Math.random() - 0.5) * 0.04,
        wobble: Math.random() * Math.PI * 2,
        wobbleSpeed: 0.03 + Math.random() * 0.02,
      });
    }

    const drawHeart = (ctx, x, y, size) => {
      ctx.beginPath();
      const topCurveHeight = size * 0.3;
      ctx.moveTo(x, y + topCurveHeight);
      ctx.bezierCurveTo(x, y, x - size / 2, y, x - size / 2, y + topCurveHeight);
      ctx.bezierCurveTo(
        x - size / 2,
        y + (size + topCurveHeight) / 2,
        x,
        y + (size + topCurveHeight) / 1.4,
        x,
        y + size
      );
      ctx.bezierCurveTo(
        x,
        y + (size + topCurveHeight) / 1.4,
        x + size / 2,
        y + (size + topCurveHeight) / 2,
        x + size / 2,
        y + topCurveHeight
      );
      ctx.bezierCurveTo(x + size / 2, y, x, y, x, y + topCurveHeight);
      ctx.fill();
    };

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        item.y += item.vy;
        item.x += Math.sin(item.wobble) * 0.6 + item.vx;
        item.wobble += item.wobbleSpeed;
        item.rotation += item.rotSpeed;

        if (item.y > height + 20) {
          item.y = -20;
          item.x = Math.random() * width;
        }

        ctx.save();
        ctx.translate(item.x, item.y);
        ctx.rotate(item.rotation);
        ctx.fillStyle = `${item.colorBase}${item.alpha})`;

        if (item.type === "heart") {
          drawHeart(ctx, 0, 0, item.size * 1.6);
        } else if (item.type === "star") {
          ctx.beginPath();
          ctx.arc(0, 0, item.size * 0.5, 0, Math.PI * 2);
          ctx.fill();
        } else {
          // Delicate luxury confetti ribbon
          ctx.fillRect(-item.size, -item.size * 0.3, item.size * 2, item.size * 0.6);
        }
        ctx.restore();
      }

      animId = requestAnimationFrame(render);
    };

    render();

    const handleResize = () => {
      width = canvas.width = canvas.parentElement.offsetWidth;
      height = canvas.height = canvas.parentElement.offsetHeight;
    };
    window.addEventListener("resize", handleResize);

    return () => {
      window.removeEventListener("resize", handleResize);
      cancelAnimationFrame(animId);
    };
  }, [isRevealed]);

  return (
    <section
      id="final"
      ref={sectionRef}
      className={`final-section ${isRevealed ? "final-revealed" : ""}`}
      aria-label="Final Celebration"
    >
      {/* Soft warm pink celebration glow background */}
      <div className="final-warm-glow" aria-hidden="true" />
      <canvas ref={canvasRef} className="final-canvas" aria-hidden="true" />

      <div className="final-content">
        <span className="final-eyebrow">{config.final.eyebrow}</span>

        <h2 className="final-title">{config.final.headline}</h2>

        <div className="final-name-wrap">
          <h1 className="final-name">{config.final.nameHeart || `${config.name} ❤️`}</h1>
        </div>

        <p className="final-wish">{config.final.wish}</p>

        <div className="final-actions">
          <button
            type="button"
            className="final-replay-btn"
            onClick={onReplay}
            aria-label="Replay the birthday surprise from the start"
          >
            <span className="replay-icon" aria-hidden="true">
              ↺
            </span>
            <span>{config.final.replayText || "Replay the journey"}</span>
          </button>
        </div>
      </div>
    </section>
  );
};

export default FinalSection;
